import { useAuth } from "@/_core/hooks/useAuth";
import { InstallAppBanner } from "@/components/InstallAppBanner";
import { ThemeToggle } from "@/components/ThemeToggle";
import { PikiSplash } from "@/components/PikiSplash";
import { trpc } from "@/lib/trpc";
import {
  Activity,
  AlertTriangle,
  ArrowLeft,
  BadgeEuro,
  CheckCircle2,
  ChevronRight,
  ClipboardList,
  Download,
  FileCheck2,
  FileWarning,
  Filter,
  Flag,
  LayoutDashboard,
  Loader2,
  MapPinned,
  Menu,
  Package,
  PauseCircle,
  Plus,
  Radio,
  Search,
  ShieldAlert,
  ShieldCheck,
  Store,
  Truck,
  UserCog,
  Users,
  X,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { Link } from "wouter";
import { toast } from "sonner";
import { buildDailyOrderMetrics, buildZoneOrderMetrics, getOperationalAlerts } from "@/lib/opsMetrics";

type Tab = "overview" | "riders" | "sos" | "partners" | "fleets" | "zones" | "incidents" | "users" | "audit";
type NavItem = { key: Tab; label: string; icon: LucideIcon; admin?: boolean; urgent?: boolean };
type Filters = { search: string; order: string; rider: string; document: string; zone: string };
const money = new Intl.NumberFormat("es-ES", { style: "currency", currency: "EUR" });
const emptyFilters: Filters = { search: "", order: "all", rider: "all", document: "all", zone: "all" };

export default function Admin() {
  const { user, loading } = useAuth();
  const isAdmin = user?.role === "admin";
  const isOps = ["admin", "fleet_manager", "zone_manager"].includes(user?.role || "");
  const [tab, setTab] = useState<Tab>("overview");
  const [mobileMenu, setMobileMenu] = useState(false);
  const [filters, setFilters] = useState<Filters>(emptyFilters);
  const [filtersOpen, setFiltersOpen] = useState(true);
  const [zoneModal, setZoneModal] = useState(false);
  const [fleetModal, setFleetModal] = useState(false);
  const [documentReview, setDocumentReview] = useState<{ rider: any; document: any } | null>(null);
  const [reviewNote, setReviewNote] = useState("");
  const [zoneDraft, setZoneDraft] = useState({ name: "", city: "", baseFee: "2.99", payout: "3.50" });
  const [fleetDraft, setFleetDraft] = useState({ name: "", zoneId: "", phone: "" });
  const overview = trpc.ops.overview.useQuery(undefined, { enabled: isOps, refetchInterval: 8_000 });
  const users = trpc.ops.listUsers.useQuery(undefined, { enabled: isAdmin });
  const audit = trpc.ops.listAudit.useQuery(undefined, { enabled: isOps && tab === "audit", refetchInterval: 12_000 });
  const refresh = () => { void overview.refetch(); void users.refetch(); void audit.refetch(); };
  const updateOrder = trpc.order.updateStatus.useMutation({ onSuccess: () => { toast.success("Estado de pedido actualizado"); refresh(); } });
  const updatePartner = trpc.ops.updatePartner.useMutation({ onSuccess: () => { toast.success("Estado del partner actualizado"); refresh(); } });
  const updateRider = trpc.ops.updateRider.useMutation({ onSuccess: () => { toast.success("Perfil de rider actualizado"); refresh(); } });
  const reviewDocument = trpc.ops.reviewRiderDocument.useMutation({ onSuccess: () => { toast.success("Documento revisado"); refresh(); } });
  const updateSOS = trpc.ops.updateSOS.useMutation({ onSuccess: () => { toast.success("Alerta SOS actualizada"); refresh(); } });
  const updateFleet = trpc.ops.updateFleet.useMutation({ onSuccess: () => { toast.success("Flota actualizada"); refresh(); } });
  const updateZone = trpc.ops.updateZone.useMutation({ onSuccess: () => { toast.success("Zona actualizada"); refresh(); } });
  const updateIncident = trpc.ops.updateIncident.useMutation({ onSuccess: () => { toast.success("Incidencia actualizada"); refresh(); } });
  const updateRole = trpc.ops.updateUserRole.useMutation({ onSuccess: () => { toast.success("Rol actualizado"); refresh(); } });
  const createZone = trpc.ops.createZone.useMutation({ onSuccess: () => { toast.success("Zona operativa creada"); setZoneModal(false); setZoneDraft({ name: "", city: "", baseFee: "2.99", payout: "3.50" }); refresh(); } });
  const createFleet = trpc.ops.createFleet.useMutation({ onSuccess: () => { toast.success("Flota creada y pendiente de activación"); setFleetModal(false); setFleetDraft({ name: "", zoneId: "", phone: "" }); refresh(); } });
  const data = overview.data;

  useEffect(() => {
    const manifest = document.querySelector<HTMLLinkElement>('link[rel="manifest"]');
    const previousManifest = manifest?.href;
    const previousTitle = document.title;
    if (manifest) manifest.href = "/manifest-admin.json";
    document.title = "PIKI Admin";
    return () => { if (manifest && previousManifest) manifest.href = previousManifest; document.title = previousTitle; };
  }, []);

  const filtered = useMemo(() => {
    const needle = filters.search.trim().toLowerCase();
    const visibleOrders = (data?.orders || []).filter((order) => (!needle || `${order.id} ${order.restaurant} ${order.riderName || ""} ${order.address}`.toLowerCase().includes(needle)) && (filters.order === "all" || order.status === filters.order));
    const visibleRiders = (data?.riders || []).filter((rider) => (!needle || `${rider.displayName} ${rider.phone || ""} ${rider.zone}`.toLowerCase().includes(needle)) && (filters.rider === "all" || rider.availability === filters.rider) && (filters.document === "all" || rider.documentsStatus === filters.document) && (filters.zone === "all" || rider.zone === filters.zone));
    return { orders: visibleOrders, riders: visibleRiders };
  }, [data, filters]);
  const metrics = useMemo(() => ({ gross: (data?.orders || []).filter((order) => order.paymentState === "paid").reduce((sum, order) => sum + order.total, 0), open: (data?.orders || []).filter((order) => !["delivered", "cancelled"].includes(order.status)).length, live: (data?.riders || []).filter((rider) => rider.availability !== "offline" && rider.status === "active" && isRecent(rider.location?.createdAt || rider.lastLocationAt)).length, sos: (data?.sos || []).filter((alert) => alert.status !== "resolved").length }), [data]);
  const submitZone = () => { if (!zoneDraft.name.trim() || !zoneDraft.city.trim()) return toast.error("Añade nombre y ciudad"); createZone.mutate({ name: zoneDraft.name.trim(), city: zoneDraft.city.trim(), baseFeeCents: Math.round(Number(zoneDraft.baseFee) * 100), riderPayoutCents: Math.round(Number(zoneDraft.payout) * 100) }); };
  const submitFleet = () => { if (!fleetDraft.name.trim() || !Number(fleetDraft.zoneId)) return toast.error("Añade nombre y selecciona una zona"); createFleet.mutate({ name: fleetDraft.name.trim(), zoneId: Number(fleetDraft.zoneId), contactPhone: fleetDraft.phone.trim() || undefined }); };
  const submitDocumentReview = (status: "verified" | "rejected") => {
    if (!documentReview) return;
    if (status === "rejected" && !reviewNote.trim()) return toast.error("Añade un comentario para que el rider pueda corregir el documento.");
    reviewDocument.mutate({ documentId: documentReview.document.id, status, reviewNote: reviewNote.trim() || undefined }, { onSuccess: () => { setDocumentReview(null); setReviewNote(""); } });
  };
  const exportDocuments = () => {
    const escape = (value: unknown) => `"${String(value ?? "").replaceAll('"', '""')}"`;
    const rows = (filtered.riders || []).flatMap((rider) => rider.documents.map((document: any) => [rider.displayName, rider.riderOpenId, rider.zone, rider.vehicle, document?.type || "missing", document?.status || "missing", document?.fileName || "", document?.expiresAt ? new Date(document.expiresAt).toLocaleDateString("es-ES") : "", document?.reviewNote || "", document?.reviewedAt ? new Date(document.reviewedAt).toLocaleString("es-ES") : ""]));
    const csv = "\uFEFF" + [["Rider", "ID rider", "Zona", "Vehículo", "Documento", "Estado", "Archivo", "Caducidad", "Comentario", "Revisado"], ...rows].map((row) => row.map(escape).join(",")).join("\n");
    const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
    const link = document.createElement("a"); link.href = url; link.download = `piki-documentos-riders-${new Date().toISOString().slice(0, 10)}.csv`; link.click(); URL.revokeObjectURL(url);
    toast.success("Exportación preparada", { description: `${rows.length} registros documentales descargados en CSV.` });
  };
  if (loading) return <div className="grid min-h-screen place-items-center bg-[#f6f7f3]"><Loader2 className="h-7 w-7 animate-spin text-[#171715]" /></div>;
  if (!isOps) return <OpsGate />;
  const allNavigation: NavItem[] = [{ key: "overview", label: "Operación", icon: LayoutDashboard }, { key: "riders", label: "Riders", icon: Users }, { key: "sos", label: "Alertas SOS", icon: ShieldAlert, urgent: metrics.sos > 0 }, { key: "partners", label: "Partners", icon: Store }, { key: "fleets", label: "Flotas", icon: Truck, admin: true }, { key: "zones", label: "Zonas", icon: MapPinned, admin: true }, { key: "incidents", label: "Incidencias", icon: Flag }, { key: "users", label: "Roles", icon: UserCog, admin: true }, { key: "audit", label: "Auditoría", icon: ClipboardList }];
  const navigation = allNavigation.filter((item) => !item.admin || isAdmin);

  return <div className="piki-app min-h-screen bg-[#f6f7f3] text-[#171715]"><PikiSplash service="admin" /><header className="sticky top-0 z-30 border-b border-[#e0e5dc] bg-[#fbfcfa]/95 backdrop-blur"><div className="mx-auto flex h-16 max-w-[1440px] items-center justify-between px-4 sm:px-6"><div className="flex items-center gap-3"><Link href="/" className="grid h-9 w-9 place-items-center rounded-full border border-[#d8e1d5] bg-white"><ArrowLeft className="h-4 w-4" /></Link><div><p className="text-[10px] font-bold uppercase tracking-[.18em] text-[#62806a]">PIKI · Centro de control</p><h1 className="font-display text-xl font-semibold tracking-[-.04em]">PIKI Admin</h1></div></div><div className="flex items-center gap-2"><span className="hidden items-center gap-2 rounded-full bg-[#e7f2e4] px-3 py-2 text-xs font-extrabold text-[#171715] sm:flex"><Radio className="h-3.5 w-3.5" /> Datos cada 8 s</span><ThemeToggle compact /><button onClick={() => setMobileMenu(true)} className="grid h-9 w-9 place-items-center rounded-full border border-[#d8e1d5] bg-white lg:hidden" aria-label="Abrir navegación"><Menu className="h-4.5 w-4.5" /></button></div></div></header>
    <div className="mx-auto grid max-w-[1440px] lg:grid-cols-[245px_1fr]"><aside className="sticky top-16 hidden h-[calc(100vh-4rem)] border-r border-[#e0e5dc] bg-[#fbfcfa] p-4 lg:block"><Nav items={navigation} active={tab} onSelect={setTab} /><div className="mt-8 rounded-2xl bg-[#143b2b] p-4 text-xs leading-relaxed text-[#cae1ca]">Estados, verificación documental y alertas SOS se actualizan desde el mismo backend que Riders.</div></aside>
      <main className="min-w-0 p-4 sm:p-6 lg:p-8">{overview.isLoading ? <Skeleton /> : <><InstallAppBanner service="admin" />
        <FilterBar filters={filters} open={filtersOpen} zones={data?.zones || []} onOpen={() => setFiltersOpen((value) => !value)} onChange={setFilters} onReset={() => setFilters(emptyFilters)} />
        {tab === "overview" && <OpsAlerts orders={filtered.orders} riders={filtered.riders} />}
        {tab === "overview" && <HistoricalAnalytics orders={filtered.orders} zones={data?.zones || []} />}
        {tab === "overview" && <PerformanceAnalytics orders={filtered.orders} riders={filtered.riders} />}
        {tab === "overview" && <Overview metrics={metrics} orders={filtered.orders} updateOrder={updateOrder} />}
        {tab === "riders" && <RidersPanel riders={filtered.riders} fleets={data?.fleets || []} updateRider={updateRider} reviewDocument={reviewDocument} onExport={exportDocuments} onOpenDocument={(rider: any, document: any) => { setDocumentReview({ rider, document }); setReviewNote(document.reviewNote || ""); }} />}
        {tab === "sos" && <SosPanel alerts={data?.sos || []} riders={data?.riders || []} updateSOS={updateSOS} />}
        {tab === "partners" && <PartnersPanel stores={data?.partners || []} updatePartner={updatePartner} />}
        {tab === "fleets" && <FleetsPanel fleets={data?.fleets || []} zones={data?.zones || []} isAdmin={isAdmin} onCreate={() => setFleetModal(true)} updateFleet={updateFleet} />}
        {tab === "zones" && <ZonesPanel zones={data?.zones || []} isAdmin={isAdmin} onCreate={() => setZoneModal(true)} updateZone={updateZone} />}
        {tab === "incidents" && <IncidentsPanel incidents={data?.incidents || []} updateIncident={updateIncident} />}
        {tab === "users" && <UsersPanel users={users.data || []} updateRole={updateRole} />}
        {tab === "audit" && <AuditPanel entries={audit.data || []} />}
      </>}</main></div>
    {mobileMenu && <div className="fixed inset-0 z-50 bg-[#10251d]/35 backdrop-blur-sm" onMouseDown={() => setMobileMenu(false)}><aside onMouseDown={(event) => event.stopPropagation()} className="h-full w-[280px] bg-[#fbfcfa] p-5 shadow-2xl"><div className="mb-6 flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#62806a]">PIKI</p><h2 className="font-display text-2xl font-semibold">Operaciones</h2></div><button onClick={() => setMobileMenu(false)} className="grid h-9 w-9 place-items-center rounded-full border border-[#d8e1d5] bg-white"><X className="h-4 w-4" /></button></div><Nav items={navigation} active={tab} onSelect={(key) => { setTab(key); setMobileMenu(false); }} /></aside></div>}
    {zoneModal && <Modal title="Nueva zona operativa" onClose={() => setZoneModal(false)}><div className="space-y-4"><Input label="Nombre de zona" value={zoneDraft.name} placeholder="Ej. Centro Xàtiva" onChange={(value) => setZoneDraft((current) => ({ ...current, name: value }))} /><Input label="Ciudad" value={zoneDraft.city} placeholder="Ej. Xàtiva" onChange={(value) => setZoneDraft((current) => ({ ...current, city: value }))} /><div className="grid grid-cols-2 gap-3"><Input label="Tarifa base (€)" value={zoneDraft.baseFee} type="number" onChange={(value) => setZoneDraft((current) => ({ ...current, baseFee: value }))} /><Input label="Base rider (€)" value={zoneDraft.payout} type="number" onChange={(value) => setZoneDraft((current) => ({ ...current, payout: value }))} /></div></div><button onClick={submitZone} disabled={createZone.isPending} className="mt-6 flex w-full items-center justify-center gap-2 rounded-xl bg-[#143b2b] py-3.5 text-sm font-extrabold text-white"><Plus className="h-4 w-4" /> {createZone.isPending ? "Creando…" : "Crear zona"}</button></Modal>}
    {fleetModal && <Modal title="Nueva flota" onClose={() => setFleetModal(false)}><div className="space-y-4"><Input label="Nombre de la flota" value={fleetDraft.name} placeholder="Ej. Xàtiva Bici 01" onChange={(value) => setFleetDraft((current) => ({ ...current, name: value }))} /><label className="block"><span className="mb-1.5 block text-sm font-bold">Zona asignada</span><select value={fleetDraft.zoneId} onChange={(event) => setFleetDraft((current) => ({ ...current, zoneId: event.target.value }))} className="w-full rounded-xl border border-[#d7e0d4] bg-white px-3 py-3 text-sm outline-none"><option value="">Seleccionar zona</option>{(data?.zones || []).map((zone) => <option key={zone.id} value={zone.id}>{zone.name} · {zone.city}</option>)}</select></label><Input label="Teléfono de contacto" value={fleetDraft.phone} type="tel" onChange={(value) => setFleetDraft((current) => ({ ...current, phone: value }))} /></div><button onClick={submitFleet} disabled={createFleet.isPending} className="mt-6 flex w-full items-center justify-center gap-2 rounded-xl bg-[#143b2b] py-3.5 text-sm font-extrabold text-white"><Plus className="h-4 w-4" /> {createFleet.isPending ? "Creando…" : "Crear flota"}</button></Modal>}
    {documentReview && <Modal title={`Revisar ${documentLabel(documentReview.document.type)}`} onClose={() => { setDocumentReview(null); setReviewNote(""); }}><div className="rounded-2xl bg-[#eef4eb] p-4"><p className="text-xs font-bold uppercase tracking-wide text-[#5e7963]">Rider</p><p className="mt-1 text-sm font-extrabold">{documentReview.rider.displayName}</p><p className="mt-1 text-xs text-[#6c7b6f]">{documentReview.rider.zone} · {documentReview.document.fileName}</p></div><div className="mt-5 overflow-hidden rounded-2xl border border-[#dce5d9] bg-[#f5f8f4]"><iframe title={`Documento de ${documentReview.rider.displayName}`} src={documentReview.document.fileUrl} className="h-[320px] w-full bg-white" /><a href={documentReview.document.fileUrl} target="_blank" rel="noreferrer" className="block border-t border-[#dce5d9] bg-white px-4 py-3 text-center text-xs font-extrabold text-[#171715]">Abrir documento en una pestaña</a></div><label className="mt-5 block"><span className="mb-1.5 block text-sm font-bold">Comentario de revisión</span><textarea value={reviewNote} onChange={(event) => setReviewNote(event.target.value)} rows={3} placeholder="Visible para el rider si requiere una corrección" className="w-full resize-none rounded-xl border border-[#d7e0d4] bg-white px-3 py-3 text-sm outline-none focus:border-[#171715]" /></label><div className="mt-6 grid grid-cols-2 gap-3"><button onClick={() => submitDocumentReview("rejected")} disabled={reviewDocument.isPending} className="rounded-xl bg-[#fff0e9] py-3 text-sm font-extrabold text-[#a85135]">Rechazar con comentario</button><button onClick={() => submitDocumentReview("verified")} disabled={reviewDocument.isPending} className="rounded-xl bg-[#143b2b] py-3 text-sm font-extrabold text-white">Aprobar documento</button></div></Modal>}
  </div>;
}

function FilterBar({ filters, open, zones, onOpen, onChange, onReset }: { filters: Filters; open: boolean; zones: any[]; onOpen: () => void; onChange: (filters: Filters) => void; onReset: () => void }) { const set = (key: keyof Filters, value: string) => onChange({ ...filters, [key]: value }); const active = Object.values(filters).filter((value) => value && value !== "all").length; return <section className="mb-7 rounded-2xl border border-[#dce5d9] bg-white p-4 shadow-sm"><div className="flex flex-wrap items-center gap-3"><div className="flex min-w-[220px] flex-1 items-center gap-2 rounded-xl bg-[#f3f6f1] px-3 py-2.5"><Search className="h-4 w-4 text-[#6b7b6e]" /><input value={filters.search} onChange={(event) => set("search", event.target.value)} placeholder="Buscar pedido, rider o zona" className="w-full bg-transparent text-sm outline-none" /></div><button onClick={onOpen} className="flex items-center gap-2 rounded-xl border border-[#d8e1d5] bg-white px-3 py-2.5 text-sm font-extrabold text-[#47634d]"><Filter className="h-4 w-4" /> Filtros {active ? <span className="grid h-5 min-w-5 place-items-center rounded-full bg-[#171715] px-1 text-[10px] text-white">{active}</span> : null}</button>{active ? <button onClick={onReset} className="text-xs font-extrabold text-[#a85135]">Limpiar</button> : null}</div>{open && <div className="mt-4 grid gap-3 border-t border-[#edf1ea] pt-4 sm:grid-cols-2 xl:grid-cols-4"><SelectFilter label="Pedido" value={filters.order} onChange={(value) => set("order", value)} options={[["all", "Todos"], ["ready", "Listos"], ["assigned", "Asignados"], ["delivering", "En ruta"], ["delivered", "Entregados"], ["cancelled", "Cancelados"]]} /><SelectFilter label="Rider" value={filters.rider} onChange={(value) => set("rider", value)} options={[["all", "Todos"], ["available", "Disponible"], ["busy", "En reparto"], ["offline", "Desconectado"]]} /><SelectFilter label="Documentos" value={filters.document} onChange={(value) => set("document", value)} options={[["all", "Todos"], ["verified", "Verificados"], ["pending", "Pendientes"], ["rejected", "Rechazados"]]} /><SelectFilter label="Zona" value={filters.zone} onChange={(value) => set("zone", value)} options={[["all", "Todas"], ...zones.map((zone) => [zone.name, zone.name])]} /></div>}</section>; }
function Overview({ metrics, orders, updateOrder }: { metrics: { gross: number; open: number; live: number; sos: number }; orders: any[]; updateOrder: ReturnType<typeof trpc.order.updateStatus.useMutation> }) { return <><PanelHead eyebrow="Operación en red" title="Control de hoy" text="Seguimiento de pedidos, disponibilidad real y excepciones de la plataforma." /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric icon={BadgeEuro} label="Volumen pagado" value={money.format(metrics.gross)} note="Cobros confirmados" dark /><Metric icon={Package} label="Pedidos abiertos" value={String(metrics.open)} note="En proceso" /><Metric icon={Radio} label="GPS en directo" value={String(metrics.live)} note="Riders activos" /><Metric icon={ShieldAlert} label="SOS activos" value={String(metrics.sos)} note={metrics.sos ? "Atención inmediata" : "Sin alertas"} alert={metrics.sos > 0} /></div><section className="mt-7 rounded-2xl bg-white p-5 shadow-sm ring-1 ring-[#e0e6dd] sm:p-7"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#62806a]">Despacho</p><h3 className="mt-1 font-display text-3xl font-semibold tracking-[-.05em]">Pedidos filtrados</h3></div><Activity className="h-5 w-5 text-[#171715]" /></div><div className="mt-6 space-y-3">{orders.length ? orders.slice(0, 40).map((order) => <div key={order.id} className="flex flex-wrap items-center gap-3 rounded-2xl border border-[#e4ebe1] p-4"><div className="min-w-0 flex-1"><p className="text-sm font-extrabold">{order.id} · {order.restaurant}</p><p className="mt-1 truncate text-xs text-[#718076]">{order.address} · {order.riderName || "Sin rider"} · {money.format(order.total)}</p></div><Status text={labelOrder(order.status)} tone={toneOrder(order.status)} />{order.deliveryVerificationState === "confirmed" && <Status text="PIN/QR OK" tone="green" />}<select value={order.status} disabled={updateOrder.isPending || order.paymentState !== "paid"} onChange={(event) => updateOrder.mutate({ id: order.id, status: event.target.value as any })} className="rounded-lg border border-[#d8e1d5] bg-white px-2.5 py-2 text-xs font-bold disabled:opacity-50"><option value="placed">Nuevo</option><option value="accepted">Aceptado</option><option value="ready">Listo</option><option value="assigned">Asignado</option><option value="picked_up">Recogido</option><option value="delivering">En ruta</option><option value="delivered">Entregado</option><option value="cancelled">Cancelado</option></select></div>) : <Empty icon={Package} title="No hay pedidos con estos filtros" text="Prueba a ajustar los filtros de operación." />}</div></section></>; }
function PerformanceAnalytics({ orders, riders }: { orders: any[]; riders: any[] }) {
  const statusRows = [
    ["Nuevos", "placed", "#90a99a"],
    ["Listos", "ready", "#ef9d45"],
    ["En ruta", "delivering", "#171715"],
    ["Entregados", "delivered", "#1a4030"],
  ].map(([label, status, color]) => ({ label, color, value: orders.filter((order) => order.status === status).length }));
  const maxOrders = Math.max(1, ...statusRows.map((row) => row.value));
  const availability = [
    ["Disponibles", "available", "#171715"],
    ["En reparto", "busy", "#ef9d45"],
    ["Fuera de línea", "offline", "#9aa39a"],
  ].map(([label, state, color]) => ({ label, color, value: riders.filter((rider) => rider.availability === state).length }));
  const activeRiders = riders.filter((rider) => rider.status === "active").length;
  const verifiedRiders = riders.filter((rider) => rider.documentsStatus === "verified").length;
  const completion = orders.length ? Math.round((orders.filter((order) => order.status === "delivered").length / orders.length) * 100) : 0;

  return <section className="mb-7 rounded-2xl bg-[#143b2b] p-5 text-white shadow-[0_16px_32px_rgba(20,59,43,.13)] sm:p-7"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#bce1bc]">Rendimiento en tiempo real</p><h3 className="mt-1 font-display text-3xl font-semibold tracking-[-.05em]">Lectura operativa</h3><p className="mt-2 text-sm text-[#c8ddc8]">Cálculos sobre los pedidos y riders visibles con los filtros actuales.</p></div><Activity className="h-6 w-6 text-[#bce1bc]" /></div><div className="mt-6 grid gap-6 lg:grid-cols-2"><div><p className="text-xs font-extrabold uppercase tracking-[.14em] text-[#bce1bc]">Flujo de pedidos</p><div className="mt-4 space-y-3">{statusRows.map((row) => <div key={row.label}><div className="mb-1.5 flex justify-between text-xs font-bold text-[#d9ead9]"><span>{row.label}</span><span>{row.value}</span></div><div className="h-2.5 overflow-hidden rounded-full bg-white/15"><div className="h-full rounded-full transition-all" style={{ width: `${(row.value / maxOrders) * 100}%`, background: row.color }} /></div></div>)}</div></div><div><p className="text-xs font-extrabold uppercase tracking-[.14em] text-[#bce1bc]">Disponibilidad de riders</p><div className="mt-4 grid gap-3 sm:grid-cols-3">{availability.map((row) => <div key={row.label} className="rounded-xl bg-white/10 p-3"><span className="block h-2 w-2 rounded-full" style={{ background: row.color }} /><p className="mt-4 text-2xl font-extrabold">{row.value}</p><p className="mt-1 text-[11px] font-bold text-[#c8ddc8]">{row.label}</p></div>)}</div><div className="mt-4 flex flex-wrap gap-3 text-xs font-bold text-[#d9ead9]"><span className="rounded-full bg-white/10 px-3 py-2">{completion}% completado</span><span className="rounded-full bg-white/10 px-3 py-2">{activeRiders} riders activos</span><span className="rounded-full bg-white/10 px-3 py-2">{verifiedRiders} documentación OK</span></div></div></div></section>;
}

function HistoricalAnalytics({ orders, zones }: { orders: any[]; zones: any[] }) {
  const daily = buildDailyOrderMetrics(orders);
  const maxDay = Math.max(1, ...daily.map((item) => item.value));
  const zoneRows = buildZoneOrderMetrics(orders, zones);
  const maxZone = Math.max(1, ...zoneRows.map((item) => item.value));
  return <section className="mb-7 rounded-2xl border border-[#dce5d9] bg-white p-5 shadow-sm sm:p-7"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#62806a]">Históricos</p><h3 className="mt-1 font-display text-3xl font-semibold tracking-[-.05em]">Días y zonas</h3><p className="mt-2 text-sm text-[#718076]">Pedidos visibles en los últimos siete días y distribución aproximada por zona de dirección.</p></div><Activity className="h-5 w-5 text-[#171715]" /></div><div className="mt-6 grid gap-7 lg:grid-cols-2"><div><div className="mb-3 flex items-center justify-between"><p className="text-xs font-extrabold uppercase tracking-[.14em] text-[#62806a]">Pedidos por día</p><span className="text-xs font-bold text-[#718076]">7 días</span></div><div className="flex h-44 items-end gap-2 rounded-xl bg-[#f6f8f5] p-4">{daily.map((item) => <div key={item.label} className="flex min-w-0 flex-1 flex-col items-center justify-end gap-2"><span className="text-[10px] font-extrabold text-[#171715]">{item.value}</span><div className="w-full rounded-t-lg bg-[#171715] transition-all" style={{ height: `${Math.max(8, (item.value / maxDay) * 100)}%` }} /><span className="text-[10px] font-bold capitalize text-[#718076]">{item.label}</span></div>)}</div></div><div><div className="mb-3 flex items-center justify-between"><p className="text-xs font-extrabold uppercase tracking-[.14em] text-[#62806a]">Pedidos por zona</p><span className="text-xs font-bold text-[#718076]">Top 5</span></div><div className="space-y-3">{zoneRows.map((item) => <div key={item.name}><div className="mb-1 flex justify-between text-xs font-bold"><span className="truncate">{item.name}</span><span>{item.value}</span></div><div className="h-2.5 overflow-hidden rounded-full bg-[#edf1eb]"><div className="h-full rounded-full bg-[#FFD72E]" style={{ width: `${(item.value / maxZone) * 100}%` }} /></div></div>)}</div></div></div></section>;
}

function OpsAlerts({ orders, riders }: { orders: any[]; riders: any[] }) {
  const { delayedOrders: delayed, staleRiders: stale } = getOperationalAlerts(orders, riders);
  if (!delayed.length && !stale.length) return <section className="mb-7 rounded-2xl border border-[#cfe2cf] bg-[#f3f9f1] p-4"><div className="flex items-center gap-3"><CheckCircle2 className="h-5 w-5 text-[#171715]" /><div><p className="text-sm font-extrabold text-[#171715]">Operación estable</p><p className="text-xs text-[#5f8068]">No hay pedidos retrasados ni riders activos con señal GPS antigua.</p></div></div></section>;
  return <section className="mb-7 rounded-2xl border border-[#efc9b9] bg-[#fff8f4] p-5 shadow-sm"><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#ffe5da] text-[#b34c31]"><AlertTriangle className="h-5 w-5" /></div><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#a85135]">Atención operativa</p><h3 className="mt-1 font-display text-2xl font-semibold">Alertas que requieren revisión</h3></div></div><div className="mt-4 grid gap-3 md:grid-cols-2">{delayed.length > 0 && <div className="rounded-xl border border-[#f0d6ca] bg-white p-4"><div className="flex items-center gap-2"><Package className="h-4 w-4 text-[#b34c31]" /><p className="text-sm font-extrabold">{delayed.length} pedido(s) retrasado(s)</p></div><p className="mt-1 text-xs text-[#718076]">Más de 40 minutos sin llegar a un estado final.</p></div>}{stale.length > 0 && <div className="rounded-xl border border-[#f0d6ca] bg-white p-4"><div className="flex items-center gap-2"><Radio className="h-4 w-4 text-[#b34c31]" /><p className="text-sm font-extrabold">{stale.length} rider(s) sin señal GPS</p></div><p className="mt-1 text-xs text-[#718076]">Sin actualización válida durante más de 90 segundos.</p></div>}</div></section>;
}

function RidersPanel({ riders, fleets, updateRider, reviewDocument, onOpenDocument, onExport }: { riders: any[]; fleets: any[]; updateRider: ReturnType<typeof trpc.ops.updateRider.useMutation>; reviewDocument: ReturnType<typeof trpc.ops.reviewRiderDocument.useMutation>; onOpenDocument: (rider: any, document: any) => void; onExport: () => void }) { return <><PanelHead eyebrow="Equipo de reparto" title="Riders y verificación" text="Activa solo cuentas con DNI, licencia y seguro verificados. Los indicadores GPS aparecen con la última señal recibida." action={<button onClick={onExport} className="flex items-center gap-2 rounded-full bg-[#143b2b] px-4 py-2.5 text-sm font-extrabold text-white"><Download className="h-4 w-4" /> Exportar CSV</button>} /><div className="space-y-4">{riders.length ? riders.map((rider) => <article key={rider.id} className="rounded-2xl border border-[#e1e8df] bg-white p-5 shadow-sm"><div className="flex flex-wrap items-start gap-3"><div className="grid h-11 w-11 place-items-center rounded-xl bg-[#eaf4e6] text-[#171715]"><Users className="h-5 w-5" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-extrabold">{rider.displayName}</p><RiderLiveLabel rider={rider} /><Status text={rider.status === "active" ? "Cuenta activa" : rider.status === "suspended" ? "Suspendida" : "Pendiente"} tone={rider.status === "active" ? "green" : rider.status === "suspended" ? "red" : "amber"} /></div><p className="mt-1 text-xs text-[#718076]">{rider.vehicle === "bike" ? "Bicicleta" : rider.vehicle} · {rider.zone} · {rider.phone || "Sin teléfono"}</p></div><select value={rider.fleetId || ""} onChange={(event) => updateRider.mutate({ riderOpenId: rider.riderOpenId, fleetId: event.target.value ? Number(event.target.value) : null })} className="rounded-lg border border-[#d8e1d5] bg-white px-2 py-2 text-xs font-bold"><option value="">Sin flota</option>{fleets.map((fleet) => <option key={fleet.id} value={fleet.id}>{fleet.name}</option>)}</select></div><div className="mt-4 grid gap-2 border-t border-[#edf2eb] pt-4 sm:grid-cols-3">{rider.documents.map((document: any, index: number) => <DocumentReview key={index} document={document} review={reviewDocument} onOpen={() => onOpenDocument(rider, document)} />)}</div><div className="mt-4 flex flex-wrap gap-2"><button disabled={updateRider.isPending || rider.documentsStatus !== "verified"} onClick={() => updateRider.mutate({ riderOpenId: rider.riderOpenId, status: rider.status === "active" ? "suspended" : "active" })} className="rounded-full bg-[#143b2b] px-3 py-2 text-xs font-extrabold text-white disabled:opacity-45">{rider.status === "active" ? "Suspender cuenta" : "Activar cuenta"}</button>{rider.documentsStatus !== "verified" && <span className="self-center text-xs font-bold text-[#a85135]">Se requieren 3 documentos verificados para activarla.</span>}</div></article>) : <Empty icon={Users} title="No hay riders con estos filtros" text="Las nuevas solicitudes y sus documentos aparecerán aquí." />}</div></>; }
function DocumentReview({ document, review, onOpen }: { document: any; review: ReturnType<typeof trpc.ops.reviewRiderDocument.useMutation>; onOpen: () => void }) { if (!document) return <div className="rounded-xl border border-dashed border-[#d8e1d5] p-3"><p className="text-xs font-bold text-[#7a897c]">Documento no subido</p></div>; return <div className="rounded-xl bg-[#f6f8f5] p-3"><div className="flex items-center justify-between gap-2"><p className="text-xs font-extrabold">{documentLabel(document.type)}</p><Status text={document.status === "verified" ? "OK" : document.status === "rejected" ? "Rechazado" : "Pendiente"} tone={document.status === "verified" ? "green" : document.status === "rejected" ? "red" : "amber"} /></div><p className="mt-2 truncate text-xs text-[#718076]">{document.fileName}</p><button onClick={onOpen} className="mt-3 w-full rounded-lg border border-[#d4e0d2] bg-white px-2.5 py-2 text-[10px] font-extrabold text-[#171715]">Revisar en detalle</button></div>; }
function SosPanel({ alerts, riders, updateSOS }: { alerts: any[]; riders: any[]; updateSOS: ReturnType<typeof trpc.ops.updateSOS.useMutation> }) { return <><PanelHead eyebrow="Seguridad" title="Alertas SOS" text="Prioridad máxima. Cada alerta contiene el rider, el pedido relacionado y la última ubicación enviada si estaba disponible." /><div className="space-y-3">{alerts.length ? alerts.map((alert) => { const rider = riders.find((item) => item.riderOpenId === alert.riderOpenId); return <article key={alert.id} className={`rounded-2xl border p-5 ${alert.status === "open" ? "border-[#eab2a2] bg-[#fff6f2]" : "border-[#e1e8df] bg-white"}`}><div className="flex flex-wrap items-start gap-3"><div className="grid h-11 w-11 place-items-center rounded-xl bg-[#b33d2b] text-white"><ShieldAlert className="h-5 w-5" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-extrabold">SOS #{alert.id} · {rider?.displayName || "Rider"}</p><Status text={alert.status === "open" ? "Abierta" : alert.status === "acknowledged" ? "Atendida" : "Resuelta"} tone={alert.status === "resolved" ? "green" : alert.status === "open" ? "red" : "amber"} /></div><p className="mt-1 text-xs text-[#718076]">Pedido: {alert.orderCode || "Sin pedido"} · {new Date(alert.createdAt).toLocaleString("es-ES")}</p>{alert.note && <p className="mt-2 text-sm text-[#693a2d]">{alert.note}</p>}{alert.latitudeE6 && <p className="mt-2 text-xs font-bold text-[#a85135]">Ubicación: {(alert.latitudeE6 / 1_000_000).toFixed(5)}, {(alert.longitudeE6 / 1_000_000).toFixed(5)}</p>}</div><select value={alert.status} disabled={updateSOS.isPending} onChange={(event) => updateSOS.mutate({ alertId: alert.id, status: event.target.value as "open" | "acknowledged" | "resolved" })} className="rounded-lg border border-[#d8e1d5] bg-white px-2.5 py-2 text-xs font-bold"><option value="open">Abierta</option><option value="acknowledged">Atendida</option><option value="resolved">Resuelta</option></select></div></article>; }) : <Empty icon={ShieldAlert} title="Sin alertas SOS" text="Cuando un rider active SOS, se mostrará aquí en tiempo real." />}</div></>; }
function PartnersPanel({ stores, updatePartner }: { stores: any[]; updatePartner: ReturnType<typeof trpc.ops.updatePartner.useMutation> }) { return <><PanelHead eyebrow="Partners" title="Altas y establecimientos" text="Aprueba los locales revisados o pausa un establecimiento que requiera intervención." /><div className="grid gap-4 md:grid-cols-2">{stores.length ? stores.map((store) => <div key={store.id} className="rounded-2xl border border-[#e1e8df] bg-white p-5"><div className="flex items-start justify-between gap-3"><div><p className="text-sm font-extrabold">{store.name}</p><p className="mt-1 text-xs text-[#718076]">{store.cuisine} · {store.address}</p></div><Status text={store.status === "active" ? "Activo" : store.status === "paused" ? "Pausado" : "En revisión"} tone={store.status === "active" ? "green" : store.status === "paused" ? "red" : "amber"} /></div><div className="mt-5 flex gap-2"><button onClick={() => updatePartner.mutate({ storeId: store.id, status: "active" })} className="flex-1 rounded-xl bg-[#171715] py-2.5 text-xs font-extrabold text-white">Aprobar</button><button onClick={() => updatePartner.mutate({ storeId: store.id, status: store.status === "paused" ? "active" : "paused" })} className="flex-1 rounded-xl border border-[#d8e1d5] bg-white py-2.5 text-xs font-extrabold text-[#58665b]">{store.status === "paused" ? "Reactivar" : "Pausar"}</button></div></div>) : <Empty icon={Store} title="No hay establecimientos" text="Las solicitudes de partner aparecerán aquí." />}</div></>; }
function FleetsPanel({ fleets, zones, isAdmin, onCreate, updateFleet }: { fleets: any[]; zones: any[]; isAdmin: boolean; onCreate: () => void; updateFleet: ReturnType<typeof trpc.ops.updateFleet.useMutation> }) { return <><PanelHead eyebrow="Fleet" title="Flotas de reparto" text="Agrupa riders, responsables y vehículos por zona de servicio." action={isAdmin ? <button onClick={onCreate} className="flex items-center gap-2 rounded-full bg-[#143b2b] px-4 py-2.5 text-sm font-extrabold text-white"><Plus className="h-4 w-4" /> Nueva flota</button> : null} /><div className="grid gap-4 md:grid-cols-2">{fleets.length ? fleets.map((fleet) => <div key={fleet.id} className="rounded-2xl border border-[#e1e8df] bg-white p-5"><p className="text-sm font-extrabold">{fleet.name}</p><p className="mt-1 text-xs text-[#718076]">{zones.find((zone) => zone.id === fleet.zoneId)?.name || "Zona sin asignar"} · {fleet.contactPhone || "Sin teléfono"}</p>{isAdmin && <button onClick={() => updateFleet.mutate({ fleetId: fleet.id, status: fleet.status === "active" ? "paused" : "active" })} className="mt-5 w-full rounded-xl border border-[#d8e1d5] bg-white py-2.5 text-xs font-extrabold text-[#56665a]">{fleet.status === "active" ? "Pausar flota" : "Activar flota"}</button>}</div>) : <Empty icon={Truck} title="No hay flotas creadas" text="Crea una flota para asignar riders." />}</div></>; }
function ZonesPanel({ zones, isAdmin, onCreate, updateZone }: { zones: any[]; isAdmin: boolean; onCreate: () => void; updateZone: ReturnType<typeof trpc.ops.updateZone.useMutation> }) { return <><PanelHead eyebrow="Cobertura" title="Zonas y tarifas" text="Define cobertura operativa, tarifa base y salida del rider." action={isAdmin ? <button onClick={onCreate} className="flex items-center gap-2 rounded-full bg-[#143b2b] px-4 py-2.5 text-sm font-extrabold text-white"><Plus className="h-4 w-4" /> Nueva zona</button> : null} /><div className="grid gap-4 md:grid-cols-2">{zones.length ? zones.map((zone) => <div key={zone.id} className="rounded-2xl border border-[#e1e8df] bg-white p-5"><div className="flex items-start justify-between gap-3"><div><p className="text-sm font-extrabold">{zone.name}</p><p className="mt-1 text-xs text-[#718076]">{zone.city} · Tarifa {money.format(zone.baseFeeCents / 100)} · Base rider {money.format(zone.riderPayoutCents / 100)}</p></div><Status text={zone.status === "active" ? "Activa" : "Pausada"} tone={zone.status === "active" ? "green" : "red"} /></div>{isAdmin && <button onClick={() => updateZone.mutate({ zoneId: zone.id, status: zone.status === "active" ? "paused" : "active" })} className="mt-5 w-full rounded-xl border border-[#d8e1d5] bg-white py-2.5 text-xs font-extrabold text-[#56665a]">{zone.status === "active" ? "Pausar zona" : "Reactivar zona"}</button>}</div>) : <Empty icon={MapPinned} title="No hay zonas configuradas" text="Crea la primera zona antes de dar de alta una flota." />}</div></>; }
function IncidentsPanel({ incidents, updateIncident }: { incidents: any[]; updateIncident: ReturnType<typeof trpc.ops.updateIncident.useMutation> }) { return <><PanelHead eyebrow="Seguimiento" title="Incidencias de reparto" text="Los reportes de riders llegan aquí para su clasificación y resolución." /><div className="space-y-3">{incidents.length ? incidents.map((item) => <div key={item.id} className="rounded-2xl border border-[#e1e8df] bg-white p-4"><div className="flex flex-wrap items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#fff0e9] text-[#ad593c]"><AlertTriangle className="h-5 w-5" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-extrabold">{item.type} {item.orderCode ? `· ${item.orderCode}` : ""}</p><Status text={item.status === "open" ? "Abierta" : item.status === "in_review" ? "En revisión" : "Resuelta"} tone={item.status === "resolved" ? "green" : item.status === "open" ? "red" : "amber"} /></div><p className="mt-1 text-xs leading-relaxed text-[#718076]">{item.notes}</p></div><select value={item.status} onChange={(event) => updateIncident.mutate({ incidentId: item.id, status: event.target.value as "open" | "in_review" | "resolved" })} className="rounded-lg border border-[#d8e1d5] bg-white px-2 py-2 text-xs font-bold"><option value="open">Abierta</option><option value="in_review">En revisión</option><option value="resolved">Resuelta</option></select></div></div>) : <Empty icon={Flag} title="Sin incidencias abiertas" text="Las incidencias enviadas desde PIKI Riders aparecerán aquí." />}</div></>; }
function UsersPanel({ users, updateRole }: { users: any[]; updateRole: ReturnType<typeof trpc.ops.updateUserRole.useMutation> }) { return <><PanelHead eyebrow="Accesos" title="Roles y permisos" text="El administrador asigna las cuentas de gestión; todos los cambios se auditan." /><div className="space-y-3">{users.map((member) => <div key={member.id} className="flex flex-wrap items-center gap-3 rounded-2xl border border-[#e1e8df] bg-white p-4"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#eef3ec] text-[#171715]"><UserCog className="h-5 w-5" /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-extrabold">{member.name || "Sin nombre"}</p><p className="truncate text-xs text-[#718076]">{member.email || member.openId}</p></div><select value={member.role} disabled={updateRole.isPending} onChange={(event) => updateRole.mutate({ openId: member.openId, role: event.target.value as any })} className="rounded-lg border border-[#d8e1d5] bg-white px-2.5 py-2 text-xs font-bold"><option value="user">Cliente</option><option value="partner">Partner</option><option value="rider">Rider</option><option value="fleet_manager">Fleet manager</option><option value="zone_manager">Gerente de zona</option><option value="admin">Admin</option></select></div>)}</div></>; }
function AuditPanel({ entries }: { entries: any[] }) { return <><PanelHead eyebrow="Trazabilidad" title="Auditoría operativa" text="Registro de cambios de estado, validaciones, localización y alertas." /><div className="space-y-3">{entries.length ? entries.map((entry) => <div key={entry.id} className="flex gap-3 rounded-2xl border border-[#e1e8df] bg-white p-4"><div className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-[#eaf4e6] text-[#171715]"><ClipboardList className="h-4 w-4" /></div><div><p className="text-sm font-extrabold">{entry.action.replaceAll("_", " ")}</p><p className="mt-1 text-xs text-[#718076]">{entry.entityType} · {entry.entityId} · {new Date(entry.createdAt).toLocaleString("es-ES")}</p></div></div>) : <Empty icon={ClipboardList} title="Aún no hay eventos" text="Los próximos cambios aparecerán aquí." />}</div></>; }
function SelectFilter({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: string[][] }) { return <label className="block"><span className="mb-1 block text-[11px] font-bold uppercase tracking-wide text-[#718076]">{label}</span><select value={value} onChange={(event) => onChange(event.target.value)} className="w-full rounded-xl border border-[#d8e1d5] bg-white px-3 py-2.5 text-sm font-bold outline-none">{options.map(([id, text]) => <option key={id} value={id}>{text}</option>)}</select></label>; }
function Nav({ items, active, onSelect }: { items: NavItem[]; active: Tab; onSelect: (tab: Tab) => void }) { return <nav className="space-y-1">{items.map(({ key, label, icon: Icon, urgent }) => <button key={key} onClick={() => onSelect(key)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-extrabold transition ${active === key ? "bg-[#e7f2e4] text-[#214d31]" : urgent ? "bg-[#fff0e9] text-[#a85135]" : "text-[#66756a] hover:bg-[#f0f4ee]"}`}><Icon className="h-4.5 w-4.5" />{label}{urgent && <span className="ml-auto h-2 w-2 rounded-full bg-[#bd4934]" />}{!urgent && <ChevronRight className="ml-auto h-4 w-4 opacity-45" />}</button>)}</nav>; }
function PanelHead({ eyebrow, title, text, action }: { eyebrow: string; title: string; text: string; action?: React.ReactNode }) { return <section className="mb-7 flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#62806a]">{eyebrow}</p><h2 className="mt-1 font-display text-4xl font-semibold tracking-[-.06em]">{title}</h2><p className="mt-2 max-w-2xl text-sm text-[#718076]">{text}</p></div>{action}</section>; }
function Metric({ icon: Icon, label, value, note, dark, alert }: { icon: LucideIcon; label: string; value: string; note: string; dark?: boolean; alert?: boolean }) { return <div className={`rounded-2xl p-5 ${dark ? "bg-[#143b2b] text-white" : "bg-white ring-1 ring-[#e0e6dd]"}`}><Icon className={`h-5 w-5 ${dark ? "text-[#bce1bc]" : alert ? "text-[#b85637]" : "text-[#171715]"}`} /><p className={`mt-5 text-xs font-bold ${dark ? "text-[#c6ddc6]" : "text-[#718076]"}`}>{label}</p><p className="mt-1 text-3xl font-extrabold tracking-[-.05em]">{value}</p><p className={`mt-2 text-xs font-bold ${dark ? "text-[#a9c9a8]" : alert ? "text-[#b85637]" : "text-[#5f8068]"}`}>{note}</p></div>; }
function Status({ text, tone }: { text: string; tone: "green" | "red" | "amber" }) { const style = tone === "green" ? "bg-[#e7f2e4] text-[#171715]" : tone === "red" ? "bg-[#fff0e9] text-[#a85135]" : "bg-[#fff6e6] text-[#9b681c]"; return <span className={`rounded-full px-2.5 py-1 text-[10px] font-extrabold uppercase tracking-wide ${style}`}>{text}</span>; }
function RiderLiveLabel({ rider }: { rider: any }) { const recent = isRecent(rider.location?.createdAt || rider.lastLocationAt); const text = rider.availability === "offline" ? "Desconectado" : recent ? rider.availability === "busy" ? "En reparto · GPS" : "Disponible · GPS" : "Señal antigua"; return <Status text={text} tone={rider.availability === "offline" ? "amber" : recent ? "green" : "red"} />; }
function Empty({ icon: Icon, title, text }: { icon: LucideIcon; title: string; text: string }) { return <div className="rounded-2xl border border-dashed border-[#cfdbcc] bg-white p-10 text-center"><Icon className="mx-auto h-7 w-7 text-[#718b76]" /><p className="mt-4 text-sm font-extrabold">{title}</p><p className="mx-auto mt-1 max-w-sm text-xs leading-relaxed text-[#718076]">{text}</p></div>; }
function Input({ label, value, onChange, placeholder, type = "text" }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string; type?: string }) { return <label className="block"><span className="mb-1.5 block text-sm font-bold">{label}</span><input value={value} onChange={(event) => onChange(event.target.value)} type={type} placeholder={placeholder} className="w-full rounded-xl border border-[#d7e0d4] bg-white px-3 py-3 text-sm outline-none focus:border-[#171715]" /></label>; }
function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) { return <div className="fixed inset-0 z-[60] grid place-items-center bg-[#10251d]/40 p-4 backdrop-blur-sm"><div className="w-full max-w-lg rounded-[2rem] bg-[#fbfcfa] p-6 shadow-2xl sm:p-8"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#62806a]">PIKI Admin</p><h2 className="mt-1 font-display text-3xl font-semibold">{title}</h2></div><button onClick={onClose} className="grid h-9 w-9 place-items-center rounded-full border border-[#d8e1d5] bg-white"><X className="h-4 w-4" /></button></div>{children}</div></div>; }
function Skeleton() { return <div className="grid gap-5"><div className="h-32 animate-pulse rounded-2xl bg-[#e3e9e0]" /><div className="h-80 animate-pulse rounded-2xl bg-[#e3e9e0]" /></div>; }
function OpsGate() { return <div className="grid min-h-screen place-items-center bg-[#f6f7f3] p-5"><div className="w-full max-w-lg rounded-[2rem] bg-white p-8 text-center shadow-xl ring-1 ring-[#e0e6dd] sm:p-12"><div className="mx-auto grid h-16 w-16 place-items-center rounded-[1.4rem] bg-[#143b2b] text-[#c8efc4]"><ShieldCheck className="h-8 w-8" /></div><p className="mt-7 text-xs font-bold uppercase tracking-[.16em] text-[#62806a]">PIKI Admin</p><h1 className="mt-2 font-display text-4xl font-semibold tracking-[-.06em]">Acceso restringido</h1><p className="mx-auto mt-4 max-w-md text-sm leading-relaxed text-[#6d7a70]">Este centro está reservado para administradores, responsables de flota y gerentes de zona.</p><Link href="/" className="mt-7 inline-flex items-center gap-2 rounded-xl bg-[#143b2b] px-5 py-3 text-sm font-extrabold text-white"><ArrowLeft className="h-4 w-4" /> Volver a PIKI</Link></div></div>; }
function isRecent(value?: Date | string | null) { return Boolean(value) && Date.now() - new Date(value as string).getTime() < 120_000; }
function labelOrder(status: string) { return ({ placed: "Nuevo", accepted: "Aceptado", ready: "Listo", assigned: "Asignado", picked_up: "Recogido", delivering: "En ruta", delivered: "Entregado", cancelled: "Cancelado" } as Record<string, string>)[status] || status; }
function toneOrder(status: string): "green" | "red" | "amber" { return status === "delivered" ? "green" : status === "cancelled" ? "red" : "amber"; }
function documentLabel(type: string) { return type === "dni" ? "DNI / NIE" : type === "driver_license" ? "Licencia de conducir" : "Seguro"; }
